package org.sleepwell.app;

import android.content.*;import android.os.*;import android.widget.*;import java.util.function.BooleanSupplier;

/** Shared alarm/quiet-preview controller. Only fresh calibrated samples can earn a unit. */
final class TiltMazeTask implements AutoCloseable {
    final SharedPreferences prefs;final String key;final BooleanSupplier current;final Runnable complete,fallback;final TiltMaze maze;final TiltMazeView view;final TextView status;final TiltSensors.Port sensor;final Handler handler=new Handler(Looper.getMainLooper());TiltMotion motion;boolean closed,started,solved,failed;int rotation;long checkpoint,startedAt;
    TiltMazeTask(LinearLayout card,SharedPreferences prefs,String run,int unit,int round,BooleanSupplier current,Runnable complete,Runnable fallback){this(card,prefs,run,unit,round,current,complete,fallback,defaultSensor(card));}
    TiltMazeTask(LinearLayout card,SharedPreferences prefs,String run,int unit,int round,BooleanSupplier current,Runnable complete,Runnable fallback,TiltSensors.Port sensor){this.prefs=prefs;this.key=ChallengePackState.key(run,unit,round);this.current=current;this.complete=complete;this.fallback=fallback;maze=ChallengePackState.maze(prefs,run,unit,round);Design.text(card,"Guide the ball to the gold circle",21,600,Design.INK);Design.text(card,"Hold your phone face-up. Calibrate while still, then tilt gently.",13,400,Design.MUTED);Design.space(card,12);view=new TiltMazeView(card.getContext(),maze);card.addView(view,new LinearLayout.LayoutParams(-1,-2));status=Design.text(card,"Press Calibrate tilt when ready",13,500,Design.BROWN);this.sensor=sensor;Design.button(card,"Calibrate tilt",false,this::calibrate);Design.button(card,"Use Math instead",false,this::chooseFallback);}
    private static TiltSensors.Port defaultSensor(LinearLayout card){try{return TiltSensors.factory.create(card.getContext());}catch(RuntimeException failure){return null;}}
    void calibrate(){if(closed||!current.getAsBoolean())return;if(sensor==null){unavailable("Tilt sensor unavailable. Use Math instead.");return;}if(started&&!stopSensor()){unavailable("Tilt sensor could not stop. Try again.");return;}started=false;failed=false;try{long now=sensor.now();motion=new TiltMotion(now);rotation=sensor.rotation();checkpoint=startedAt=now;status.setText("Hold still and face-up to calibrate…");started=true;boolean accepted=sensor.start(this::sample);if(!accepted){unavailable("Tilt sensor could not start. Use Math instead.");return;}handler.removeCallbacksAndMessages(null);handler.postDelayed(watchdog,2500);}catch(RuntimeException failure){unavailable("Tilt sensor could not start. Use Math instead.");}}
    private void sample(long time,double x,double y,double z){if(closed||!started||solved||failed||!current.getAsBoolean())return;try{long now=sensor.now();if(sensor.rotation()!=rotation){calibrate();return;}double[] move=motion.sample(time,now,x,y,z,rotation);status.setText(motion.calibrated()?"Tilt gently · reach the gold target":"Hold still and face-up to calibrate…");if(move==null)return;maze.move(move[0],move[1]);view.invalidate();if(now-checkpoint>500_000_000L){if(!ChallengePackState.save(prefs,key,maze)){unavailable("Maze progress could not be saved. Try again or use Math.");return;}checkpoint=now;}if(maze.solved()){if(!stopSensor()){unavailable("Tilt sensor could not stop. Try again.");return;}started=false;if(!ChallengePackState.save(prefs,key,maze)){unavailable("Maze completion could not be saved. Try again.");return;}solved=true;handler.removeCallbacksAndMessages(null);if(current.getAsBoolean())complete.run();}}catch(RuntimeException failure){unavailable("Tilt reading unavailable. Use Math instead.");}}
    final Runnable watchdog=new Runnable(){public void run(){if(closed||!started||failed)return;if(!current.getAsBoolean()){close();return;}try{long last=motion.last();if(sensor.now()-(last==0?startedAt:last)>2_500_000_000L){unavailable("No stable tilt readings. Recalibrate or use Math.");return;}handler.postDelayed(this,1000);}catch(RuntimeException unavailable){unavailable("Tilt readings unavailable. Recalibrate or use Math.");}}};
    private void unavailable(String text){failed=true;handler.removeCallbacksAndMessages(null);if(sensor!=null&&stopSensor())started=false;status.setText(text);}
    private void chooseFallback(){if(closed||!current.getAsBoolean())return;if(sensor!=null&&!stopSensor()){unavailable("Tilt sensor could not stop. Try again.");return;}started=false;if(!ChallengePackState.chooseFallback(prefs,key)){status.setText("Math fallback could not be saved. Try again.");return;}handler.removeCallbacksAndMessages(null);closed=true;fallback.run();}
    private boolean stopSensor(){try{return sensor==null||sensor.stop();}catch(RuntimeException failure){return false;}}
    boolean released(){return !started;}
    @Override public void close(){handler.removeCallbacksAndMessages(null);closed=true;if(sensor!=null&&stopSensor())started=false;if(current.getAsBoolean()&&!solved)try{if(!ChallengePackState.save(prefs,key,maze))status.setText("Maze checkpoint could not be saved.");}catch(RuntimeException failure){status.setText("Maze checkpoint could not be saved.");}}
}
